         if (node1 == node2) {
             return 0;
         }

         int t1 = node1.getNodeType();
         int t2 = node2.getNodeType();
         if (t1 == Node.ATTRIBUTE_NODE && t2 != Node.ATTRIBUTE_NODE) {
             return -1;
         }
         if (t1 != Node.ATTRIBUTE_NODE && t2 == Node.ATTRIBUTE_NODE) {
             return 1;
         }
         if (t1 == Node.ATTRIBUTE_NODE && t2 == Node.ATTRIBUTE_NODE) {
             NamedNodeMap map = ((Node) getNode()).getAttributes();
             int length = map.getLength();
             for (int i = 0; i < length; i++) {
