92     @Override
93     protected PointVectorValuePair doOptimize() {
94         checkParameters();
95 
96         // Retrieve convergence checker.
97         ConvergenceChecker<PointVectorValuePair> checker = getConvergenceChecker();
98 
99         // Variables for storing the current state of the optimization.
100         int eval = 0;
101         ArrayRealVector currentPoint = new ArrayRealVector(getStartPoint());
102         ArrayRealVector currentObjective = computeObjective(currentPoint);
103         double currentCost = currentObjective.getNorm();
104 
105         // Store the best point found so far.
106         ArrayRealVector bestPoint = currentPoint;
107         double bestCost = currentCost;
108 
109         // Perform iterations until convergence.
110         int iter = 0;
111         while (true) {
112             ++iter;
113 
114             // Compute the jacobian and the residuals.
115             BlockRealMatrix jacobian = computeJacobian(currentPoint);
116             ArrayRealVector residuals = currentObjective;
117 
118             // Solve the normal equations.
119             RealMatrix normal = jacobian.transpose().multiply(jacobian);
119             DecompositionSolver solver = useLU ? new LUDecomposition(normal).getSolver()
120                 : new QRDecomposition(normal).getSolver();
121             ArrayRealVector delta = solver.solve(jacobian.transpose().multiply(residuals));
122 
123             // Update the current point.
124             currentPoint = currentPoint.add(delta);
125 
126             // Compute the new objective value and cost.
127             currentObjective = computeObjective(currentPoint);
128             currentCost = currentObjective.getNorm();
129 
130             // Check for convergence.
131             if (checker.converged(iter, new PointVectorValuePair(bestPoint, bestCost),
132                                  new PointVectorValuePair(currentPoint, currentCost))) {
133                 break;
134             }
135 
136             // Update the best point if necessary.
137             if (currentCost < bestCost) {
138                 bestPoint = currentPoint;
139                 bestCost = currentCost;
140             }
141 
142             // Increment the evaluation count.
143             eval++;
144             if (eval >= getMaxEvaluations()) {
145                 throw new ConvergenceException(LocalizedFormats.MAXIMUM_NUMBER_OF_EVALUATIONS_EXCEEDED, getMaxEvaluations());
146             }
147         }
148 
149         return new PointVectorValuePair(bestPoint, bestCost);
