         @Override
         public double getValue() {
             return iter.value();
         }

         /** {@inheritDoc} */
         @Override
         public void setValue(double value) {
             entries.put(iter.key(), value);
         }

         /** {@inheritDoc} */
         @Override
         public int getIndex() {
             return iter.key();
         }

     }

